mapper.select:
/*SQL-ID : isry.csemd.cmmn.mapper.CsemdMapper selectInstCmb : 자원제공주체(교육기관) select box data 리스트 */
SELECT DISTINCT INST_NO -- 기관번호 ,INST_NM -- 기관명 FROM SAA000 A INNER JOIN SAC100 B ON B.CMMNS_CD_ID = 'APLY_RQST_TRGT_INST_SE_CD' AND (B.ADDTNG_MNG_VALUE2 = A.INST_NO OR B.ADDTNG_MNG_VALUE3 = A.INST_NO)
WHERE B.ADDTNG_MNG_VALUE1 = #{UNT_TASKWK_SE_CD} AND (INST_NO = #{INST_NO} OR #{INST_TYPE_SE_CD} < '5' OR #{AUTHRT_SE_CD} = '3300706' OR SUBSTR(#{AUTHRT_SE_CD},2,2) = '10')
